; === Sub_PlayerPosition ===
; Convert Sprite 0 pixel position to character-grid cell.
; Y-cell = (Sprite0_Y - $2C) >> 3 (divide by 8).
; X-cell = (Sprite0_X - $0C) >> 1 + X-MSB-half.
; Result used to read the screen character at that cell,
; then dispatch to If_NotPlatform / If_TouchingMushroom / rope, etc.
player_position     sta var_player_dir   ; save collision check point selector (0-3) ; x-ref: $536d, $53a5, $546f, $c530, $c535, ...
                    lda $d001            ; Sprite 0 Y Pos
                    sec 
                    sbc #$2c             ; subtract 44px Y origin offset (sprites start at pixel 50)
                    lsr a                ; divide by 8 to get character row
                    lsr a
                    lsr a
                    tay                  ; Y = character row number
                    lda $d000            ; Sprite 0 X Pos
                    sec 
                    sbc #$0c             ; subtract 12px X origin offset
                    bcc b_2A00           ; if X < left boundary, clamp via b_2A00
                    lsr a                ; halve X (step 1 of /8 pixel-to-char conversion)
                    sta var_player_x_low
                    lda $d010            ; Sprites 0-7 MSB of X coordinate
