; =-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-
; Updates the Sprites X-MSB register ($D010) then retriggles SID Voice 3 with
; a preset frequency and triangle waveform from the table at f_45B3.
; Steps: (1) store A -> $D010; (2) gate off Voice 3; (3) copy 7-byte preset
; table into Voice 3 registers ($D40E-$D414), re-enabling the gate on X=4.
; 
; Inputs:  A = new value for $D010 (Sprites 0-7 X-MSB bitmask, pre-computed by caller)
; Outputs: None (A, X clobbered)
; Side Effects: $D010 updated; SID Voice 3 re-triggered with preset freq/envelope
; =-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-
set_xmsb_retrigger_v3
                    sta $d010            ; write caller-computed sprite X-MSB bitmask to VIC-II $D010 ; x-ref: $c816; Sprites 0-7 MSB of X coordinate
                    lda #$00
                    sta $d412            ; gate off Voice 3 before reconfiguring its registers; Voice 3: Control Register
                    ldx #$00
b_2F0A              lda f_45B3,x         ; load preset voice 3 value (freq lo/hi, pw lo/hi, ctrl, atk/dec, sust/rel) ; x-ref: $2f13
                    sta $d40e,x          ; write to SID Voice 3 register $D40E+X; at X=4 re-enables gate (ctrl=$11 = triangle+gate); Voice 3: Frequency Control - Low-Byte
                    inx 
                    cpx #$07             ; loop 7x for all Voice 3 regs ($D40E-$D414)
                    bne b_2F0A
                    rts 
                    .byte $9d
                    .byte $fa, $07, $a9, $00, $8d, $ff, $ff, $8a
                    .byte $48, $bd, $6d, $cf, $85, $fb, $a9, $45
                    .byte $85, $fc, $a0, $00, $b1, $fb, $99, $ff
                    .byte $ff, $c8, $c0, $07, $d0, $f6, $68, $aa
                    .byte $60
set_enemy_colour    .byte $9d, $29, $d0  ; x-ref: $c6e3
                    lda f_575E,x
                    sta ptr_lo
                    lda f_CF24,x
                    sta ptr_hi
                    ldy #$00
; Read byte from zero-page indirect pointer ($FB/$FC+Y) into sprite data table f_CF15,X.
read_zp_to_cf15     lda (ptr_lo),y
                    sta sprite_dir_state,x
                    rts 
; =-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-
; Thin wrapper that starts SID music initialisation.
; Delegates entirely to s_60CA, which silences all SID registers ($D400-$D41C),
; sets the music-data pointers ($B7/$B8, $B9/$BA -> $61F8) and installs the
; music-player IRQ handler at $0314/$0315 (pointing to the player at $60F5).
; 
; Inputs:  None
; Outputs: None
; Side Effects: SID registers cleared; CIA IRQ vector ($0314/$0315) set to SID player
; =-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-
init_sid_music      jsr sid_setup        ; init SID chip, set music data pointers, install music-player IRQ at $0314/$0315 ; x-ref: $2e91
