                    sta $d405            ; Voice 1: Attack / Decay Cycle Control
                    jsr music_data_handler
                    sta $d40c            ; Voice 2: Attack / Decay Cycle Control
                    jsr music_data_handler
                    sta $d406            ; Voice 1: Sustain / Release Cycle Control
                    jsr music_data_handler
                    sta $d40d            ; Voice 2: Sustain / Release Cycle Control
                    jmp music_cmd_dispatch
                    jsr music_data_handler
                    sta $d402            ; Voice 1: Pulse Waveform Width - Low-Byte
                    jsr music_data_handler
                    sta $d403            ; Voice 1: Pulse Waveform Width - High-Nybble
                    jsr music_data_handler
                    sta $d409            ; Voice 2: Pulse Waveform Width - Low-Byte
                    jsr music_data_handler
                    sta $d40a            ; Voice 2: Pulse Waveform Width - High-Nybble
                    jmp music_cmd_dispatch
                    .byte $a5, $b9, $85, $b7, $a5, $ba, $85, $b8
                    .byte $4c, $31, $ea
; Silence SID: zero all voice registers, restore KERNAL IRQ vector to $EA31.
disable_music       lda #$00
                    ldx #$20
b_61D6              sta $d400,x          ; x-ref: $61da; Voice 1: Frequency Control - Low-Byte
                    dex 
                    bne b_61D6
                    sei 
                    lda #$31
                    sta irq_vector_lo    ; IRQ
                    lda #$ea
                    sta irq_vector_hi    ; IRQ
                    cli 
                    rts 
music_data_handler  inc snd_ptr1_lo      ; x-ref: $610e, $6114, $6126, $612c, $613e, ...
                    bne b_61EF
                    inc snd_ptr1_hi
b_61EF              lda (snd_ptr1_lo),y  ; x-ref: $61eb
                    rts 
